function wordMap(rows, lang, name) {
  var map = {};
  var list = Array.isArray(rows) ? rows : [];
  for (var i = 0; i < list.length; i++) if (list[i] && list[i].key) map[list[i].key] = String(list[i][lang] || list[i].en || '').split('{b}').join(name);
  return map;
}
function fill(text, vars) { var t = String(text || ''); for (var k in vars) t = t.split('{' + k + '}').join(String(vars[k])); return t; }
function langOf(v) { return String(v) === 'fr' ? 'fr' : 'en'; }
function nameOf(v) { var n = String(v || '').trim(); return n || 'Pip'; }

var PAINTS = [{"token":"--robot-coral","hex":"#FF7A59","name":{"en":"coral","fr":"corail"}},{"token":"--robot-orange","hex":"#FFB347","name":{"en":"orange","fr":"orange"}},{"token":"--robot-sun","hex":"#FFD166","name":{"en":"sunny","fr":"soleil"}},{"token":"--robot-leaf","hex":"#3FA66B","name":{"en":"leaf","fr":"feuille"}},{"token":"--robot-sky","hex":"#5FB4E8","name":{"en":"sky","fr":"ciel"}},{"token":"--robot-violet","hex":"#8F6BFF","name":{"en":"violet","fr":"violet"}},{"token":"--robot-pink","hex":"#F06BA8","name":{"en":"pink","fr":"rose"}},{"token":"--robot-slate","hex":"#7A8CA3","name":{"en":"slate","fr":"ardoise"}}];
var EYES = [{"id":"round","word":"eyeRound"},{"id":"happy","word":"eyeHappy"},{"id":"wink","word":"eyeWink"}];
